components.css:
.ds-tray{background:var(--color-panel, #111318);border:1px solid var(--color-border, #252a35);border-radius:16px;padding:24px;font-family:var(--font-sans, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);max-width:380px;transition:border-color var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)),background-color var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1))}
.ds-tray-label{display:block;font-size:.875rem;font-weight:500;letter-spacing:.025em;color:var(--color-text-secondary, #b4b9c4);margin-bottom:8px}
.ds-tray-body{margin:0;font-size:.875rem;line-height:1.625;color:var(--color-text, #eceef2)}

.ds-btn-primary{font-family:var(--font-sans, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);font-size:.875rem;font-weight:600;letter-spacing:.025em;background:var(--color-accent, #5b7cfa);color:var(--color-bg, #08090c);border:none;border-radius:12px;padding:12px 16px;cursor:pointer;transition:filter var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)),transform var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1))}
.ds-btn-primary:hover{filter:brightness(1.1)}
.ds-btn-primary:active{transform:scale(.98)}
.ds-btn-primary:focus-visible{outline:none;box-shadow:0 0 0 2px var(--color-panel, #111318),0 0 0 4px var(--color-accent, #5b7cfa)}
.ds-btn-primary:disabled{opacity:.5;cursor:not-allowed;filter:none}

.ds-btn-stop{font-family:var(--font-sans, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);font-size:.875rem;font-weight:600;letter-spacing:.025em;background:var(--color-danger-bg, rgba(248,113,113,.1));color:var(--color-danger, #f87171);border:1px solid rgba(248,113,113,.6);border-radius:12px;padding:12px 16px;cursor:pointer;transition:background var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)),transform var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1))}
.ds-btn-stop:hover{background:rgba(248,113,113,.2)}
.ds-btn-stop:active{transform:scale(.98)}
.ds-btn-stop:focus-visible{outline:none;box-shadow:0 0 0 2px var(--color-panel, #111318),0 0 0 4px var(--color-accent, #5b7cfa)}

.ds-btn-ghost{font-family:var(--font-sans, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);font-size:.875rem;font-weight:600;letter-spacing:.025em;background:var(--color-panel-2, #181c24);color:var(--color-text, #eceef2);border:1px solid var(--color-border-strong, #5b6782);border-radius:12px;padding:12px 16px;cursor:pointer;transition:border-color var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)),color var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)),transform var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1))}
.ds-btn-ghost:hover{border-color:var(--color-accent, #5b7cfa);color:var(--color-accent, #5b7cfa)}
.ds-btn-ghost:active{transform:scale(.98)}
.ds-btn-ghost:focus-visible{outline:none;box-shadow:0 0 0 2px var(--color-panel, #111318),0 0 0 4px var(--color-accent, #5b7cfa)}
.ds-btn-ghost:disabled{opacity:.5;cursor:not-allowed;border-color:var(--color-border-strong, #5b6782);color:var(--color-text, #eceef2)}

.ds-input-draft{display:block;width:100%;box-sizing:border-box;min-height:160px;resize:vertical;font-family:var(--font-sans, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);font-size:.875rem;line-height:1.625;color:var(--color-text, #eceef2);caret-color:var(--color-accent, #5b7cfa);background:var(--color-panel-2, #181c24);border:1px solid var(--color-border-strong, #5b6782);border-radius:12px;padding:12px;outline:none;transition:border-color var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)),box-shadow var(--duration-fast, 150ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1))}
.ds-input-draft::placeholder{color:var(--color-text-tertiary, #6e7382)}
.ds-input-draft:focus{border-color:var(--color-accent, #5b7cfa);box-shadow:0 0 0 2px rgba(91,124,250,.3)}
.ds-input-draft:disabled{opacity:.6}

.ds-output-well{font-family:var(--font-sans, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);font-size:.875rem;line-height:1.625;color:var(--color-text, #eceef2);background:var(--color-panel-2, #181c24);border:1px solid var(--color-border-subtle, #1d212b);border-radius:12px;padding:12px;min-height:160px;max-width:380px;box-sizing:border-box;white-space:pre-wrap;overflow-wrap:break-word}
.ds-caret{display:inline-block;width:8px;height:1.1em;margin-left:2px;vertical-align:text-bottom;background:var(--color-accent, #5b7cfa);animation:ds-blink 1s steps(2,start) infinite}
@keyframes ds-blink{to{opacity:0}}
@media (prefers-reduced-motion:reduce){.ds-caret{animation:none;opacity:1}}

.ds-slider{font-family:var(--font-sans, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif);max-width:340px;display:flex;flex-direction:column;gap:8px}
.ds-slider-head{display:flex;align-items:center;justify-content:space-between}
.ds-slider-name{font-size:.875rem;font-weight:500;letter-spacing:.025em;color:var(--color-text-secondary, #b4b9c4)}
.ds-slider-score{font-family:var(--font-mono, ui-monospace, "SF Mono", "Fira Code", Menlo, Consolas, monospace);font-size:.75rem;font-variant-numeric:tabular-nums;color:var(--color-text, #eceef2);background:var(--color-panel-2, #181c24);border:1px solid var(--color-border, #252a35);border-radius:6px;padding:4px 8px;min-width:34px;text-align:center}
.ds-slider-range{width:100%;accent-color:var(--color-accent, #5b7cfa);cursor:pointer}
.ds-slider-range:focus-visible{border-radius:12px;outline:none;box-shadow:0 0 0 2px var(--color-panel, #111318),0 0 0 4px var(--color-accent, #5b7cfa)}
.ds-slider-foot{display:flex;justify-content:space-between;font-size:.6875rem;color:var(--color-text-tertiary, #6e7382)}
.ds-slider-active{color:var(--color-accent, #5b7cfa);font-weight:500}
